import React from "react";

export default function SignIn({ onLogin }) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #F9FAF8 0%, #F9FAF8 100%)",
        color: "#000000ff",
        padding: "2rem",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        textAlign: "center",
      }}
    >
      <h2 style={{ fontSize: "2.5rem", fontWeight: "700", marginBottom: "0.5rem" }}>
        Welcome to ApolloX
      </h2>
      <p style={{ fontSize: "1.2rem", marginBottom: "2rem", opacity: 0.9 }}>
        Sign in to explore sentiment analysis, word clouds, and summaries.
      </p>
      <button
        onClick={() => {
          console.log("Sign In button clicked");
          onLogin();
        }}
        style={{
          background: "linear-gradient(135deg, #F2994A 0%, #F2C94C 100%)",
          border: "none",
          borderRadius: "30px",
          padding: "12px 40px",
          fontSize: "1.2rem",
          fontWeight: "600",
          color: "#1a1a1a",
          cursor: "pointer",
          boxShadow: "0 4px 15px rgba(242, 201, 76, 0.6)",
          transition: "all 0.3s ease",
          minWidth: "160px",
        }}
        onMouseEnter={(e) => {
          e.target.style.background = "linear-gradient(135deg, #F2C94C 0%, #F2994A 100%)";
          e.target.style.color = "#fff";
          e.target.style.boxShadow = "0 6px 20px rgba(242, 153, 74, 0.8)";
        }}
        onMouseLeave={(e) => {
          e.target.style.background = "linear-gradient(135deg, #F2994A 0%, #F2C94C 100%)";
          e.target.style.color = "#1a1a1a";
          e.target.style.boxShadow = "0 4px 15px rgba(242, 201, 76, 0.6)";
        }}
      >
        Sign In
      </button>
    </div>
  );
}
